#include <bits/stdc++.h>
using namespace std;

long long countPairs(vector<int>& x, vector<int>& y, long long K) {
    sort(y.begin(), y.end());
    int m = y.size();
    long long ans = 0;
    for (int xi : x) {
        if (K == 0) {
            ans += m;
        } else if (xi == 0) {
            continue;
        } else {
            long long need = (K + xi - 1) / xi; // 向上取整
            int pos = lower_bound(y.begin(), y.end(), need) - y.begin();
            ans += m - pos;
        }
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
